        "detail": "（1）证明：$\\because \\angle ACB=90^\\circ$，$\\angle ACM+\\angle ACB+\\angle BCN=180^\\circ$，<br>$\\therefore \\angle ACM+\\angle BCN=90^\\circ$，<br>$\\because AM\\perp l$，$BN\\perp l$，<br>$\\therefore \\angle AMC=\\angle BNC=90^\\circ$，<br>$\\therefore \\angle MAC+\\angle ACM=90^\\circ$，<br>$\\therefore \\angle MAC=\\angle BCN$，<br>在$\\triangle ACM$和$\\triangle CBN$中，<br>$\\begin{cases} \\angle MAC=\\angle BCN \\\\ \\angle AMC=\\angle BNC=90^\\circ \\\\ AC=CB \\end{cases}$，<br>$\\therefore \\triangle ACM\\cong\\triangle CBN(\\text{AAS})$，<br>$\\therefore AM=CN$，$BN=CM$，<br>$\\because MN=CM+CN$，<br>$\\therefore MN=AM+BN$；<br>（2）解：$DE=AD+BE$成立，理由如下：<br>$\\because \\angle ACD+\\angle ACB+\\angle BCE=180^\\circ$，$\\angle ADC=\\angle ACB=\\alpha$，$\\angle ADC+\\angle DAC+\\angle ACD=180^\\circ$，<br>$\\therefore \\angle BCE=\\angle DAC$，<br>在$\\triangle ACD$和$\\triangle CBE$中，<br>$\\begin{cases} \\angle DAC=\\angle ECB \\\\ \\angle ADC=\\angle CEB=\\alpha \\\\ AC=CB \\end{cases}$，<br>$\\therefore \\triangle ACD\\cong\\triangle CBE(\\text{AAS})$，<br>$\\therefore AD=CE$，$CD=BE$，<br>又$\\because DE=DC+CE$，<br>$\\therefore DE=AD+BE$；<br>（3）解：$\\because \\angle A=\\angle EDF$，$\\angle A+\\angle AED+\\angle ADE=180^\\circ$，$\\angle ADE+\\angle EDF+\\angle BDF=180^\\circ$，<br>$\\therefore \\angle AED=\\angle BDF$，<br>在$\\triangle AED$和$\\triangle BDF$中，<br>$\\begin{cases} \\angle A=\\angle B \\\\ \\angle AED=\\angle BDF \\\\ DE=FD \\end{cases}$，<br>$\\therefore \\triangle AED\\cong\\triangle BDF(\\text{AAS})$，<br>$\\therefore AE=DB$，$AD=BF$，<br>$\\because AB=AD+DB$，$AE=3$，$BF=5$，<br>$\\therefore AB=BF+AE=5+3=8$．"
