    // Restart question numbering within each imported chapter/section.
    const chapterQuestionCounts = new Map();
    QUESTION_BANK.forEach(question => {
      // Older Word imports may label solution questions as 'answer'; the UI uses 'calc'.
      if (question.type === 'answer' || question.typeName === '解答题') {
        question.type = 'calc';
        question.typeName = '解答题';
      }
      const chapter = String(question.chapter || '未命名专题');
      const nextNumber = (chapterQuestionCounts.get(chapter) || 0) + 1;
      question.number = nextNumber;
      chapterQuestionCounts.set(chapter, nextNumber);
    });

